     1	import { Socket as PhoenixSocket } from "phoenix";
     2	import { assign, createActor, fromPromise, setup } from "xstate";
     3	import type { PhoenixPayload } from "phoenix";
     4	import { authSessionSocketToken } from "@dhc/api-client";
     5	
     6	/**
     7	 * Notification realtime bridge for NotificationCenter (ALE-164).
     8	 *
     9	 * Replaces the Supabase-Realtime-backed bridge with a Phoenix-Session-backed
    10	 * one. The browser can no longer read the HTTP-only `_dhc_session` cookie to
    11	 * pass it as a Phoenix JS `authToken`, and `new WebSocket(url, protocols)`
    12	 * has no `withCredentials` so a cross-origin socket cannot send the cookie.
    13	 * Instead, the bridge fetches a short-lived, JS-readable socket token from
    14	 * `GET /api/auth/socket-token` (credentialed, so the cookie is sent) and
    15	 * passes it as `authToken`.
    16	 *
    17	 * Socket tokens are valid for 60 seconds, and Phoenix JS's own reconnect loop
    18	 * reuses the original `authToken`, so the bridge owns recovery (ALE-337).
    19	 * Sockets are constructed with a `reconnectAfterMs` that never fires in
    20	 * practice, so Phoenix never reconnects by itself. When the live socket
    21	 * errors or closes, the bridge leaves its channel, disconnects it, waits a
    22	 * bounded backoff, fetches a fresh token, and connects a new socket. Every
    23	 * successful (re)join calls `invalidate()` so events missed while
    24	 * disconnected are recovered by an authoritative refetch, and resets the
    25	 * backoff. A token fetch that hangs past a timeout is abandoned and retried;
    26	 * a token that resolves after `destroy()` or after a newer attempt has
    27	 * started is dropped. A retired socket that revives itself anyway (Phoenix's
    28	 * heartbeat-timeout or `pageshow` paths) is disconnected again on its next
    29	 * lifecycle event.
    30	 *
    31	 * The channel carries only a best-effort `notification_created` invalidation
    32	 * signal; notification data, pagination, and unread counts remain owned by
    33	 * the Phoenix HTTP API.
    34	 *
    35	 * The bridge is best-effort: connection, authentication, join, and reconnect
    36	 * failures never throw to the caller. They emit diagnostic warnings and are
    37	 * retried with backoff (a failed or empty token fetch included), except a
    38	 * rejected HTTP session, which ends this bridge until it is mounted again. Channel
    39	 * rejoin on a still-connected socket is left to Phoenix: it needs no token,
    40	 * only schedules while the socket is connected, and the bridge leaves the
    41	 * channel before retiring its socket, so the two never compete. HTTP queries and
    42	 * mutations remain usable regardless of realtime state.
    43	 */
    44	
    45	export type InvalidateNotifications = () => void;
    46	
    47	/**
    48	 * Fetches a short-lived Phoenix socket token. `null` is temporarily unavailable;
    49	 * an unauthorized session ends recovery. HTTP queries remain independent.
    50	 */
    51	export const socketSessionUnauthorized = Symbol("socket-session-unauthorized");
    52	export type SocketTokenFetcher = () => Promise<
    53		string | null | typeof socketSessionUnauthorized
    54	>;
    55	
    56	/**
    57	 * Factory that constructs a Phoenix `Socket`. Injected so tests can substitute
    58	 * the client boundary without importing the real `phoenix` package.
    59	 */
    60	export interface RealtimePush {
    61		receive(
    62			status: string,
    63			callback: (response: PhoenixPayload) => void,
    64		): RealtimePush;
    65		send(timeout?: number): RealtimePush;
    66	}
    67	
    68	export interface RealtimeChannel {
    69		readonly topic: string;
    70		join(timeout?: number): RealtimePush;
    71		leave(timeout?: number): RealtimePush;
    72		on(
    73			event: string,
    74			callback: (payload: PhoenixPayload, ref?: string) => void,
    75		): string;
    76	}
    77	
    78	export interface RealtimeSocket {
    79		connect(): void;
    80		disconnect(callback?: () => void, code?: number, reason?: string): void;
    81		channel(topic: string): RealtimeChannel;
    82		onError(callback: (reason?: string) => void): string;
    83		onClose(callback: () => void): string;
    84		onOpen(callback: () => void): string;
    85	}
    86	
    87	export interface RealtimeSocketOptions {
    88		authToken: string;
    89		/**
    90		 * Phoenix's own reconnect delay. The bridge owns recovery, so this keeps
    91		 * Phoenix's reconnect timer from firing within any realistic page life.
    92		 */
    93		reconnectAfterMs: (tries: number) => number;
    94	}
    95	
    96	export type SocketFactory = (
    97		url: string,
    98		options: RealtimeSocketOptions,
    99	) => RealtimeSocket;
   100	
   101	export interface NotificationRealtimeConfig {
   102		/** Public Phoenix WebSocket socket URL, e.g. `wss://host/socket`. */
   103		socketUrl: string;
   104		/** Fetches a short-lived Phoenix socket token (via the session cookie). */
   105		getSocketToken?: SocketTokenFetcher;
   106		/** Invalidates the Notifications infinite-query key (authoritative refetch). */
   107		invalidate: InvalidateNotifications;
   108		/** Constructs the Phoenix Socket. Defaults to the real `phoenix` client. */
   109		createSocket?: SocketFactory;
   110	}
   111	
   112	export interface NotificationRealtimeHandle {
   113		/** Tear down channel and disconnect socket. Idempotent. */
   114		destroy: () => void;
   115	}
   116	
   117	const NOTIFICATION_CREATED_EVENT = "notification_created";
   118	
   119	/**
   120	 * Delay before each consecutive reconnect attempt. The last entry is the
   121	 * ceiling, so a failing token endpoint is hit at most every 30 seconds.
   122	 */
   123	const RECONNECT_BACKOFF_MS = [1_000, 2_000, 5_000, 10_000, 30_000] as const;
   124	
   125	/** A token fetch that hasn't settled by now is abandoned and retried. */
   126	const TOKEN_FETCH_TIMEOUT_MS = 10_000;
   127	
   128	/**
   129	 * Largest delay `setTimeout` honours (~24.8 days). Larger values, including
   130	 * `Infinity`, overflow and fire immediately, so this is the "never" handed to
   131	 * Phoenix's reconnect timer.
   132	 */
   133	const NEVER_MS = 2_147_483_647;
   134	
   135	const defaultCreateSocket: SocketFactory = (url, options) => {
   136		// Imported at module top-level so Vite bundles the real `phoenix` client.
   137		// Tests inject a substitute via `createSocket`, so this default never runs
   138		// under test.
   139		return new PhoenixSocket(url, options);
   140	};
   141	
   142	const defaultGetSocketToken: SocketTokenFetcher = async () => {
   143		const { data, error, response } = await authSessionSocketToken();
   144		if (response?.status === 401) return socketSessionUnauthorized;
   145		return error || !data ? null : data.data.socketToken;
   146	};
   147	
   148	function warn(context: string, cause: unknown): void {
   149		console.warn(`NotificationCenter realtime: ${context}`, cause);
   150	}
   151	
   152	/**
   153	 * Connect a Phoenix Socket, join the user's Notification topic, and keep it
   154	 * connected. Every connect (initial and recovery) fetches a fresh socket
   155	 * token because the token is short-lived; a socket error or close replaces
   156	 * the socket after a bounded backoff.
   157	 *
   158	 * Returns a handle whose `destroy()` cancels any pending reconnect, leaves
   159	 * the channel, and disconnects the socket. All realtime failures are
   160	 * swallowed and logged; `invalidate` is only ever called as a best-effort
   161	 * refetch trigger, never as an error path.
   162	 *
   163	 * The `userId` (topic suffix) is read from the decoded socket token —
   164	 * Phoenix assigns `current_user.sub` on connect, and the channel join
   165	 * authorizes the topic against that sub. The browser does not need to know
   166	 * its own user id here; it learns the topic from the server's join response.
   167	 */
   168	type NotificationRealtimeMachineInput = {
   169		socketUrl: string;
   170		getSocketToken: SocketTokenFetcher;
   171		invalidate: InvalidateNotifications;
   172		createSocket: SocketFactory;
   173	};
   174	
   175	type NotificationRealtimeMachineContext = NotificationRealtimeMachineInput & {
   176		socket: RealtimeSocket | null;
   177		channel: RealtimeChannel | null;
   178		attemptsSinceJoin: number;
   179	};
   180	
   181	type NotificationRealtimeMachineEvent =
   182		| { type: "SOCKET_LOST"; socket: RealtimeSocket; reason?: string }
   183		| { type: "CONNECTION_FAILED"; cause: unknown }
   184		| { type: "CHANNEL_JOINED"; socket: RealtimeSocket }
   185		| { type: "NOTIFICATION_CREATED"; socket: RealtimeSocket }
   186		| { type: "DESTROY" }
   187		// XState emits these for the invoked token-fetch actor. Listing them keeps
   188		// guards and actions type-safe while the actor remains cancellable on exit.
   189		| {
   190				type: "xstate.done.actor.fetchSocketToken";
   191				output: Awaited<ReturnType<SocketTokenFetcher>>;
   192		  }
   193		| { type: "xstate.error.actor.fetchSocketToken"; error: unknown };
   194	
   195	function disconnect(socket: RealtimeSocket, context: string): void {
   196		try {
   197			socket.disconnect();
   198		} catch (error) {
   199			warn(context, error);
   200		}
   201	}
   202	
   203	function leave(channel: RealtimeChannel): void {
   204		try {
   205			channel
   206				.leave()
   207				.receive("error", (reason) => warn("channel leave rejected", reason));
   208		} catch (error) {
   209			warn("channel leave threw", error);
   210		}
   211	}
   212	
   213	/**
   214	 * A definition is safely shared, but each connection factory below creates its
   215	 * own actor. Its context contains every injected browser dependency and the
   216	 * current socket/channel; no recovery state is shared between page mounts.
   217	 */
   218	const notificationRealtimeMachine = setup({
   219		// SAFETY: XState reads these placeholders as types only.
   220		types: {
   221			context: {} as NotificationRealtimeMachineContext,
   222			events: {} as NotificationRealtimeMachineEvent,
   223			input: {} as NotificationRealtimeMachineInput,
   224		},
   225		actors: {
   226			fetchSocketToken: fromPromise<
   227				Awaited<ReturnType<SocketTokenFetcher>>,
   228				SocketTokenFetcher
   229			>(async ({ input }) => input()),
   230		},
   231		delays: {
   232			backoff: ({ context }) =>
   233				RECONNECT_BACKOFF_MS[
   234					Math.min(context.attemptsSinceJoin, RECONNECT_BACKOFF_MS.length - 1)
   235				],
   236		},
   237		guards: {
   238			isUnauthorized: ({ event }) =>
   239				event.type === "xstate.done.actor.fetchSocketToken" &&
   240				event.output === socketSessionUnauthorized,
   241			hasToken: ({ event }) =>
   242				event.type === "xstate.done.actor.fetchSocketToken" &&
   243				event.output !== socketSessionUnauthorized &&
   244				!!event.output,
   245			isCurrentSocket: ({ context, event }) =>
   246				("socket" in event && context.socket === event.socket) || false,
   247		},
   248		actions: {
   249			warnUnavailableToken: () => warn("socket token unavailable", undefined),
   250			warnTokenTimeout: () => warn("socket token fetch timed out", undefined),
   251			warnTokenFailure: ({ event }) => {
   252				if (event.type === "xstate.error.actor.fetchSocketToken") {
   253					warn("socket token fetch threw", event.error);
   254				}
   255			},
   256			warnConnectionFailure: ({ event }) => {
   257				if (event.type === "CONNECTION_FAILED") {
   258					warn("realtime connection failed", event.cause);
   259				}
   260			},
   261			invalidate: ({ context }) => {
   262				try {
   263					context.invalidate();
   264				} catch (error) {
   265					warn("invalidation callback threw", error);
   266				}
   267			},
   268			resetBackoff: assign({ attemptsSinceJoin: 0 }),
   269			countRetry: assign(({ context }) => ({
   270				attemptsSinceJoin: context.attemptsSinceJoin + 1,
   271			})),
   272			constructSocket: assign(({ context, event, self }) => {
   273				if (
   274					event.type !== "xstate.done.actor.fetchSocketToken" ||
   275					!event.output ||
   276					event.output === socketSessionUnauthorized
   277				) {
   278					return {};
   279				}
   280	
   281				let socket: RealtimeSocket;
   282				try {
   283					socket = context.createSocket(context.socketUrl, {
   284						authToken: event.output,
   285						reconnectAfterMs: () => NEVER_MS,
   286					});
   287				} catch (error) {
   288					self.send({ type: "CONNECTION_FAILED", cause: error });
   289					return {};
   290				}
   291	
   292				const retired = () => {
   293					const snapshot = self.getSnapshot();
   294					return (
   295						snapshot.status !== "active" || snapshot.context.socket !== socket
   296					);
   297				};
   298				const lost = (reason?: string) => {
   299					if (retired()) {
   300						disconnect(socket, "retired socket disconnect threw");
   301						return;
   302					}
   303					warn("socket lost", reason);
   304					self.send({ type: "SOCKET_LOST", socket, reason });
   305				};
   306	
   307				try {
   308					socket.onError(lost);
   309					socket.onClose(() => lost());
   310					socket.onOpen(() => {
   311						if (retired()) disconnect(socket, "retired socket disconnect threw");
   312					});
   313				} catch (error) {
   314					warn("socket lifecycle wiring failed", error);
   315				}
   316				try {
   317					const channel = socket.channel("notifications:self");
   318					channel.on(NOTIFICATION_CREATED_EVENT, () => {
   319						const snapshot = self.getSnapshot();
   320						if (
   321							snapshot.status === "active" &&
   322							snapshot.context.socket === socket
   323						) {
   324							self.send({ type: "NOTIFICATION_CREATED", socket });
   325						}
   326					});
   327					return { socket, channel };
   328				} catch (error) {
   329					self.send({ type: "CONNECTION_FAILED", cause: error });
   330					disconnect(socket, "socket disconnect threw");
   331					return { socket: null, channel: null };
   332				}
   333			}),
   334			connectAndJoin: ({ context, self }) => {
   335				if (!context.socket || !context.channel) return;
   336				try {
   337					context.socket.connect();
   338					context.channel
   339						.join()
   340						.receive("ok", () =>
   341							self.send({ type: "CHANNEL_JOINED", socket: context.socket! }),
   342						)
   343						.receive("error", (reason) => warn("channel join rejected", reason))
   344						.receive("timeout", () => warn("channel join timed out", undefined));
   345				} catch (error) {
   346					self.send({ type: "CONNECTION_FAILED", cause: error });
   347				}
   348			},
   349			retireCurrent: assign(({ context }) => {
   350				if (context.channel) leave(context.channel);
   351				if (context.socket) disconnect(context.socket, "socket disconnect threw");
   352				return { socket: null, channel: null };
   353			}),
   354			retireStaleSocket: ({ event }) => {
   355				if (event.type === "SOCKET_LOST") {
   356					disconnect(event.socket, "retired socket disconnect threw");
   357				}
   358			},
   359		},
   360	}).createMachine({
   361		id: "notificationRealtime",
   362		context: ({ input }) => ({
   363			...input,
   364			socket: null,
   365			channel: null,
   366			attemptsSinceJoin: 0,
   367		}),
   368		initial: "fetchingToken",
   369		states: {
   370			fetchingToken: {
   371				invoke: {
   372					id: "fetchSocketToken",
   373					src: "fetchSocketToken",
   374					input: ({ context }) => context.getSocketToken,
   375					onDone: [
   376						{ guard: "isUnauthorized", target: "stopped" },
   377						{
   378							guard: "hasToken",
   379							target: "connected",
   380							actions: "constructSocket",
   381						},
   382						{ target: "backingOff", actions: "warnUnavailableToken" },
   383					],
   384					onError: { target: "backingOff", actions: "warnTokenFailure" },
   385				},
   386				after: {
   387					[TOKEN_FETCH_TIMEOUT_MS]: {
   388						target: "backingOff",
   389						actions: "warnTokenTimeout",
   390					},
   391				},
   392			},
   393			connected: {
   394				entry: "connectAndJoin",
   395				on: {
   396					SOCKET_LOST: [
   397						{
   398							guard: "isCurrentSocket",
   399							target: "backingOff",
   400							actions: "retireCurrent",
   401						},
   402						{ actions: "retireStaleSocket" },
   403					],
   404					CONNECTION_FAILED: {
   405						target: "backingOff",
   406						actions: ["warnConnectionFailure", "retireCurrent"],
   407					},
   408					CHANNEL_JOINED: {
   409						guard: "isCurrentSocket",
   410						actions: ["resetBackoff", "invalidate"],
   411					},
   412					NOTIFICATION_CREATED: {
   413						guard: "isCurrentSocket",
   414						actions: "invalidate",
   415					},
   416				},
   417			},
   418			backingOff: {
   419				after: { backoff: { target: "fetchingToken", actions: "countRetry" } },
   420			},
   421			stopped: { type: "final", entry: "retireCurrent" },
   422		},
   423		on: { DESTROY: { target: ".stopped" } },
   424	});
   425	
   426	/**
   427	 * Connect a Phoenix Socket and join the user's notification topic. The returned
   428	 * handle is unchanged; only its implementation is now a per-handle XState actor.
   429	 */
   430	export function connectNotificationRealtime(
   431		config: NotificationRealtimeConfig,
   432	): NotificationRealtimeHandle {
   433		const actor = createActor(notificationRealtimeMachine, {
   434			input: {
   435				socketUrl: config.socketUrl,
   436				getSocketToken: config.getSocketToken ?? defaultGetSocketToken,
   437				invalidate: config.invalidate,
   438				createSocket: config.createSocket ?? defaultCreateSocket,
   439			},
   440		});
   441		actor.start();
   442		return {
   443			destroy: () => {
   444				if (actor.getSnapshot().status !== "active") return;
   445				actor.send({ type: "DESTROY" });
   446				actor.stop();
   447			},
   448		};
   449	}

