169: ): NotificationRealtimeHandle {
170: 	const {
171: 		socketUrl,
172: 		getSocketToken = REDACTED,
173: 		invalidate,
174: 		createSocket = defaultCreateSocket,
175: 	} = config;
176: 
177: 	let socket: RealtimeSocket | null = null;
178: 	let channel: RealtimeChannel | null = null;
179: 	let destroyed = false;
180: 	/** Incremented per connect attempt; a stale attempt drops its results. */
181: 	let attempt = 0;
182: 	/** Attempts since the last successful join; indexes the backoff. */
183: 	let attemptsSinceJoin = 0;
184: 	let reconnectTimer: ReturnType<typeof setTimeout> | null = null;
185: 
186: 	function invalidateSafely(): void {
187: 		try {
188: 			invalidate();
189: 		} catch (error) {
190: 			warn("invalidation callback threw", error);
191: 		}
192: 	}
193: 
194: 	function teardownChannel(): void {
195: 		if (!channel) return;
196: 		const current = channel;
197: 		channel = null;
198: 		try {
199: 			current
200: 				.leave()
201: 				.receive("error", (reason) => warn("channel leave rejected", reason));
202: 		} catch (error) {
203: 			warn("channel leave threw", error);
204: 		}
205: 	}
206: 
207: 	function disconnectSocket(): void {
208: 		if (!socket) return;
209: 		const current = socket;
210: 		socket = null;
211: 		try {
212: 			current.disconnect();
213: 		} catch (error) {
214: 			warn("socket disconnect threw", error);
215: 		}
216: 	}
217: 
218: 	/**
219: 	 * Drop the current connection and schedule a fresh-token connect after the
220: 	 * next backoff delay. Disconnecting the dead socket also resets Phoenix's
221: 	 * own reconnect timer, so the two loops never compete.
222: 	 */
223: 	function scheduleReconnect(): void {
224: 		if (destroyed || reconnectTimer) return;
225: 		teardownChannel();
226: 		disconnectSocket();
227: 		const delay =
228: 			RECONNECT_BACKOFF_MS[
229: 				Math.min(attemptsSinceJoin, RECONNECT_BACKOFF_MS.length - 1)
230: 			];
231: 		attemptsSinceJoin += 1;
232: 		reconnectTimer = setTimeout(() => {
233: 			reconnectTimer = null;
234: 			void connectWithFreshToken();
235: 		}, delay);
236: 	}
237: 
238: 	/**
239: 	 * Fetch a fresh socket token and connect. Replaces any existing connection
240: 	 * wholesale: a reconnect after a long disconnect needs a fresh token
241: 	 * because the socket-token validity window is short.
242: 	 */
243: 	async function connectWithFreshToken(): Promise<void> {
244: 		if (destroyed) return;
245: 		const current = ++attempt;
246: 		const isStale = () => destroyed || current !== attempt;
247: 
248: 		// A hung fetch would otherwise stall recovery forever. Abandoning it
249: 		// supersedes this attempt, so its late result is dropped below.
250: 		const fetchTimeout = setTimeout(() => {
251: 			if (isStale()) return;
252: 			attempt += 1;
253: 			warn("socket token fetch timed out", undefined);
254: 			scheduleReconnect();
255: 		}, TOKEN_FETCH_TIMEOUT_MS);
256: 
257: 		let token: Awaited<ReturnType<SocketTokenFetcher>>;
258: 		try {
259: 			token = await getSocketToken();
260: 		} catch (error) {
261: 			if (isStale()) return;
262: 			warn("socket token fetch threw", error);
263: 			scheduleReconnect();
264: 			return;
265: 		} finally {
266: 			clearTimeout(fetchTimeout);
267: 		}
268: 		if (isStale()) return;
269: 		if (token === socketSessionUnauthorized) {
270: 			destroy();
271: 			return;
272: 		}
273: 		if (!token) {
274: 			warn("socket token unavailable", undefined);
275: 			scheduleReconnect();
276: 			return;
277: 		}
278: 
279: 		teardownChannel();
280: 		disconnectSocket();
281: 
282: 		let newSocket: RealtimeSocket;
283: 		try {
284: 			newSocket = createSocket(socketUrl, {
285: 				authToken: token,
286: 				reconnectAfterMs: () => NEVER_MS,
287: 			});
288: 		} catch (error) {
289: 			warn("socket construction failed", error);
290: 			scheduleReconnect();
291: 			return;
292: 		}
293: 		socket = newSocket;
294: 
295: 		// A retired socket (replaced, or its bridge destroyed) can still revive
296: 		// itself: Phoenix's heartbeat-timeout teardown schedules a reconnect even
297: 		// after `disconnect()`, and `pageshow` reconnects after bfcache restore.
298: 		// Any lifecycle event from a retired socket disconnects it again.
299: 		const isRetired = () => destroyed || socket !== newSocket;
300: 		const retire = () => {
301: 			try {
302: 				newSocket.disconnect();
303: 			} catch (error) {
304: 				warn("retired socket disconnect threw", error);
305: 			}
306: 		};
307: 		const onSocketLost = (context: string) => (reason?: string) => {
308: 			if (isRetired()) {
309: 				retire();
310: 				return;
311: 			}
312: 			warn(context, reason);
313: 			scheduleReconnect();
314: 		};
315: 		try {
316: 			newSocket.onError(onSocketLost("socket error"));
317: 			newSocket.onClose(onSocketLost("socket closed"));
318: 			newSocket.onOpen(() => {
319: 				if (isRetired()) retire();
320: 			});
321: 		} catch (error) {
322: 			warn("socket lifecycle wiring failed", error);
323: 		}
324: 
325: 		try {
326: 			newSocket.connect();
327: 		} catch (error) {
328: 			warn("socket connect failed", error);
329: 			scheduleReconnect();
330: 			return;
331: 		}
332: 
333: 		// The channel topic is `notifications:<sub>`. The browser does not know
334: 		// its own sub (the socket token is opaque), so it joins a generic
335: 		// `notifications:self` topic and relies on the server's join/3 to
336: 		// authorize against `socket.assigns.current_user.sub`. The channel
337: 		// module already rejects any mismatched topic suffix.
338: 		let newChannel: RealtimeChannel;
339: 		try {
340: 			newChannel = newSocket.channel("notifications:self");
341: 		} catch (error) {
342: 			warn("channel construction failed", error);
343: 			return;
344: 		}
345: 		channel = newChannel;
346: 
347: 		try {
348: 			newChannel.on(NOTIFICATION_CREATED_EVENT, () => invalidateSafely());
349: 		} catch (error) {
350: 			warn("channel.on wiring failed", error);
351: 		}
352: 
353: 		// Rejoin (and initial join) invalidation: recovers events missed while
354: 		// disconnected by refetching authoritative state. The `ok` hook fires
355: 		// on the initial join and on every successful rejoin after an error.
356: 		try {
357: 			newChannel
358: 				.join()
359: 				.receive("ok", () => {
360: 					if (socket !== newSocket) return;
361: 					attemptsSinceJoin = 0;
362: 					invalidateSafely();
363: 				})
364: 				.receive("error", (reason) => warn("channel join rejected", reason))
365: 				.receive("timeout", () => warn("channel join timed out", undefined));
366: 		} catch (error) {
367: 			warn("channel join threw", error);
368: 		}
369: 	}
370: 
371: 	// Fire and forget; all failures are swallowed inside `connectWithFreshToken`.
372: 	void connectWithFreshToken();
373: 
374: 	function destroy() {
375: 		if (destroyed) return;
376: 		destroyed = true;
377: 		if (reconnectTimer) {
378: 			clearTimeout(reconnectTimer);
379: 			reconnectTimer = null;
380: 		}
381: 		teardownChannel();
382: 		disconnectSocket();
383: 	}
384: 	return { destroy };
385: }

