     1	import { afterEach, describe, expect, it, vi } from "vitest";
     2	import {
     3		connectNotificationRealtime,
     4		socketSessionUnauthorized,
     5		type RealtimeChannel,
     6		type RealtimePush,
     7		type RealtimeSocket,
     8		type SocketFactory,
     9	} from "./notification-realtime.svelte";
    10	import type { PhoenixPayload } from "phoenix";
    11	import { getClient } from "@dhc/api-client";
    12	
    13	/**
    14	 * Focused NotificationCenter realtime bridge tests (ALE-164).
    15	 *
    16	 * The bridge now fetches a short-lived Phoenix socket token via a
    17	 * `getSocketToken` callback (the browser exchanges the `_dhc_session` cookie
    18	 * for it at `GET /api/auth/socket-token`) and passes it as `authToken` to the
    19	 * Phoenix JS `Socket`. There is no Supabase client in the bridge anymore.
    20	 *
    21	 * Covered:
    22	 *   1. socket token supplied as authToken + `notifications:self` topic joined;
    23	 *   2. notification_created invalidates the exact query key;
    24	 *   3. successful initial join and rejoin invalidate the same key;
    25	 *   4. socket error/close reconnects with a fresh token, with bounded backoff,
    26	 *      suppressing stale token fetches and replacing the dead socket;
    27	 *   5. SIGNED_OUT-equivalent (destroy) leaves/disconnects without breaking HTTP;
    28	 *   6. connection/join errors stay silent and never block invalidation calls;
    29	 *   7. a failed, empty, or hung token fetch creates no socket and is retried
    30	 *      with backoff; a late token from a superseded attempt is dropped;
    31	 *   8. a retired socket that reconnects on its own is disconnected again.
    32	 *
    33	 * The Phoenix client boundary is substituted with an in-memory fake so no
    34	 * WebSocket globals or network are involved. Full browser E2E is out of scope.
    35	 */
    36	
    37	type PushReceiver = {
    38		status: string;
    39		cb: (response: PhoenixPayload) => void;
    40	}[];
    41	
    42	interface FakeChannel extends RealtimeChannel {
    43		topic: string;
    44		receivers: PushReceiver;
    45		onCallbacks: Map<string, ((payload: PhoenixPayload) => void)[]>;
    46		leaveMock: ReturnType<typeof vi.fn>;
    47	}
    48	
    49	interface FakeSocket extends RealtimeSocket {
    50		url: string;
    51		authToken: string;
    52		connected: boolean;
    53		disconnected: boolean;
    54		channels: FakeChannel[];
    55		disconnectCount: number;
    56		reconnectAfterMs: (tries: number) => number;
    57		onErrorCb?: (reason?: string) => void;
    58		onCloseCb?: () => void;
    59		onOpenCb?: () => void;
    60	}
    61	
    62	function makeFakeChannel(topic: string): FakeChannel {
    63		const receivers: PushReceiver = [];
    64		const onCallbacks = new Map<string, ((payload: PhoenixPayload) => void)[]>();
    65		const leaveMock = vi.fn();
    66	
    67		const push = (): RealtimePush => {
    68			const api: RealtimePush = {
    69				receive(status: string, cb: (response: PhoenixPayload) => void) {
    70					receivers.push({ status, cb });
    71					return api;
    72				},
    73				send() {
    74					return api;
    75				},
    76			};
    77			return api;
    78		};
    79	
    80		const channel: FakeChannel = {
    81			topic,
    82			receivers,
    83			onCallbacks,
    84			leaveMock,
    85			join: vi.fn(() => push()),
    86			leave: vi.fn(() => {
    87				leaveMock();
    88				return push();
    89			}),
    90			on: vi.fn((event: string, cb: (payload: PhoenixPayload) => void) => {
    91				const list = onCallbacks.get(event) ?? [];
    92				list.push(cb);
    93				onCallbacks.set(event, list);
    94				return event;
    95			}),
    96		};
    97		return channel;
    98	}
    99	
   100	function makeFakeSocket(
   101		url: string,
   102		options: Parameters<SocketFactory>[1],
   103	): FakeSocket {
   104		const { authToken, reconnectAfterMs } = options;
   105		const channels: FakeChannel[] = [];
   106		const socket: FakeSocket = {
   107			url,
   108			authToken,
   109			connected: false,
   110			disconnected: false,
   111			disconnectCount: 0,
   112			reconnectAfterMs,
   113			channels,
   114			connect: vi.fn(function (this: FakeSocket) {
   115				this.connected = true;
   116			}),
   117			disconnect: vi.fn(function (this: FakeSocket) {
   118				this.disconnected = true;
   119				this.connected = false;
   120				this.disconnectCount += 1;
   121			}),
   122			channel: vi.fn((topic: string) => {
   123				const ch = makeFakeChannel(topic);
   124				channels.push(ch);
   125				return ch;
   126			}),
   127			onError: vi.fn((cb: (reason?: string) => void) => {
   128				socket.onErrorCb = cb;
   129				return "error";
   130			}),
   131			onClose: vi.fn((cb: () => void) => {
   132				socket.onCloseCb = cb;
   133				return "close";
   134			}),
   135			onOpen: vi.fn((cb: () => void) => {
   136				socket.onOpenCb = cb;
   137				return "open";
   138			}),
   139		};
   140		return socket;
   141	}
   142	
   143	function emitChannelEvent(
   144		channel: FakeChannel,
   145		event: string,
   146		payload: PhoenixPayload = {},
   147	) {
   148		for (const cb of channel.onCallbacks.get(event) ?? []) {
   149			cb(payload);
   150		}
   151	}
   152	
   153	function resolveJoin(
   154		channel: FakeChannel,
   155		status: string,
   156		response: PhoenixPayload = {},
   157	) {
   158		for (const r of channel.receivers) {
   159			if (r.status === status) r.cb(response);
   160		}
   161	}
   162	
   163	function flush() {
   164		return new Promise((resolve) => setTimeout(resolve, 0));
   165	}
   166	
   167	const SOCKET_URL = "ws://localhost:4000/socket";
   168	
   169	function setup({
   170		getSocketToken,
   171		createSocket,
   172	}: {
   173		getSocketToken: () => Promise<string | null>;
   174		createSocket: SocketFactory;
   175	}) {
   176		const invalidate = vi.fn();
