   186	let createdSockets: FakeSocket[] = [];
   187	const createSocketFactory = (): SocketFactory => {
   188		createdSockets = [];
   189		return (url, options) => {
   190			const socket = makeFakeSocket(url, options);
   191			createdSockets.push(socket);
