   196	// Upper bound on a single reconnect delay; waiting this long must always be
   197	// enough for the next attempt to start.
   198	const RECONNECT_CEILING_MS = 30_000;
   199	
   200	/** Advance fake time in small steps until `done()` holds (bounded). */
   201	async function advanceUntil(
   202		done: () => boolean,
   203		maxMs = 2 * RECONNECT_CEILING_MS,
   204	) {
   205		for (let elapsed = 0; !done() && elapsed < maxMs; elapsed += 100) {
   206			await vi.advanceTimersByTimeAsync(100);
